const scoreChip = r => { const s = parseFloat(r.persona_score); if (isNaN(s)) return '<span class="chip">–</span>'; const c = s >= 8 ? 'hi' : s >= 6 ? 'mid' : 'lo'; return `<span class="chip ${c}">${s}</span>`; };
