const envNum = (v, d) => { const n = parseFloat(v); return isNaN(n) ? d : n; };
const envBool = (v, d) => (v === undefined || v === '') ? d : !/^(false|0|no|off)$/i.test(String(v).trim());
const TEST_MODE = envBool(ENV.TEST_MODE, true);          // true = every email goes ONLY to TEST_ADDRESS and nothing is logged as sent
const TEST_ADDRESS = String(ENV.TEST_ADDRESS || '');
const TEST_COUNT = envNum(ENV.TEST_COUNT, 1);                   // how many sample emails to send in test mode
const DAILY_LIMIT = envNum(ENV.DAILY_LIMIT, 5);                  // real sends per day (UTC date). Start at 5 and raise slowly
const SENDER_NAME = ENV.SENDER_NAME || '[Your name]';
const SENDER_ROLE = ENV.SENDER_ROLE || 'Founder';
const SENDER_COMPANY = ENV.SENDER_COMPANY || '[Your company]';
const SENDER_WEBSITE = ENV.SENDER_WEBSITE || '';
const SUBJECT = ENV.SUBJECT || 'The project you had to turn down';
const OFFER = ENV.OFFER || '[Describe your offer in one or two sentences]';
const BOOKING_LINK = ENV.BOOKING_LINK || '[your booking link]';
// Daily mix by persona_score: high (9-10), medium (7-8), low (6 or below). A tier with no leads at all passes its quota to medium, then high, then low.
const TIERS = [
  { name: 'high',   test: (s) => s >= 9,          quota: 2 },
  { name: 'medium', test: (s) => s >= 7 && s < 9, quota: 2 },
  { name: 'low',    test: (s) => s < 7,           quota: 1 }
];

// ---------- Office-hours scheduling: send when the lead's office opens ----------
const RESPECT_OFFICE_HOURS = envBool(ENV.RESPECT_OFFICE_HOURS, true);   // false = ignore office hours (a manual "send now" run)
const OPEN_HOUR = envNum(ENV.OPEN_HOUR, 9);                 // local office-opening hour
const WINDOW_HOURS = envNum(ENV.WINDOW_HOURS, 2);              // a lead is eligible from OPEN_HOUR until OPEN_HOUR + WINDOW_HOURS (local time)
const DEFAULT_TZ = ENV.DEFAULT_TZ || 'Asia/Dubai';     // used when a lead has no usable location or country domain
const SUN_THU = [0, 1, 2, 3, 4], MON_FRI = [1, 2, 3, 4, 5];
const PLACES = [  // [pattern, timezone, working days]
  [/\b(uae|dubai|abu dhabi|sharjah|ajman|emirates)\b/i, 'Asia/Dubai', MON_FRI],
  [/\b(ksa|saudi|riyadh|jeddah|dammam|khobar)\b/i, 'Asia/Riyadh', SUN_THU],
  [/\b(oman|muscat)\b/i, 'Asia/Muscat', SUN_THU],
  [/\b(qatar|doha)\b/i, 'Asia/Qatar', SUN_THU],
  [/\b(kuwait)\b/i, 'Asia/Kuwait', SUN_THU],
  [/\b(bahrain|manama)\b/i, 'Asia/Bahrain', SUN_THU],
  [/\b(egypt|cairo)\b/i, 'Africa/Cairo', SUN_THU],
  [/\b(uk|united kingdom|england|scotland|wales|london|leeds|manchester)\b/i, 'Europe/London', MON_FRI],
  [/\b(india|ahmedabad|gurgaon|mumbai|delhi|bangalore|bengaluru|pune|chennai|hyderabad)\b/i, 'Asia/Kolkata', MON_FRI],
  [/\b(poland|warsaw)\b/i, 'Europe/Warsaw', MON_FRI],
  [/\b(germany|berlin)\b/i, 'Europe/Berlin', MON_FRI],
  [/\b(pakistan|karachi|lahore)\b/i, 'Asia/Karachi', MON_FRI],
  [/\b(usa|us|united states|lewes|delaware|new york)\b/i, 'America/New_York', MON_FRI]   // assumes US Eastern time
];
const TLD_TZ = { ae: 'Asia/Dubai', sa: 'Asia/Riyadh', om: 'Asia/Muscat', qa: 'Asia/Qatar', kw: 'Asia/Kuwait', bh: 'Asia/Bahrain', eg: 'Africa/Cairo', uk: 'Europe/London', in: 'Asia/Kolkata', pl: 'Europe/Warsaw', de: 'Europe/Berlin', pk: 'Asia/Karachi' };
const WORKDAYS_BY_TZ = { 'Asia/Riyadh': SUN_THU, 'Asia/Muscat': SUN_THU, 'Asia/Qatar': SUN_THU, 'Asia/Kuwait': SUN_THU, 'Asia/Bahrain': SUN_THU, 'Africa/Cairo': SUN_THU };
const zoneOf = (r) => {
  const loc = String(r.location || '');
  for (const [re, tz, days] of PLACES) if (re.test(loc)) return { tz, days };
  const tld = (emailDomain(r.email).split('.').pop() || '').toLowerCase();
  const tz = TLD_TZ[tld] || DEFAULT_TZ;
  return { tz, days: WORKDAYS_BY_TZ[tz] || MON_FRI };
};
const localNow = (tz) => {
  const p = new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short', hour: '2-digit', hourCycle: 'h23' }).formatToParts(new Date());
  const get = (t) => (p.find(x => x.type === t) || {}).value;
  return { wd: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(get('weekday')), hour: parseInt(get('hour'), 10) };
};
const officeOpen = (r) => {
  if (!RESPECT_OFFICE_HOURS) return true;
  const z = zoneOf(r), n = localNow(z.tz);
  return z.days.includes(n.wd) && n.hour >= OPEN_HOUR && n.hour < OPEN_HOUR + WINDOW_HOURS;
};
