if (!TEST_MODE && placeholders) {
  throw new Error('Fill in SENDER_NAME, SENDER_ROLE, SENDER_COMPANY, OFFER and BOOKING_LINK in your .env file before sending to real leads (or keep TEST_MODE=true).');
}

const remaining = TEST_MODE ? TEST_COUNT : Math.max(0, DAILY_LIMIT - sentToday);
const score = (r) => parseFloat(r.persona_score) || 0;
const tierName = (s) => (TIERS.find(t => t.test(s)) || TIERS[1]).name;
const pool = rows
  .filter(r => r.status === 'approved' && r.email && !sentSet.has(r.email.toLowerCase()))
  .sort((a, b) => score(b) - score(a));

// Per-tier quota for today, minus what has already gone out today.
const quota = {}; for (const t of TIERS) quota[t.name] = t.quota;
for (const name of ['low', 'high', 'medium']) {
  if (pool.some(r => tierName(score(r)) === name)) continue;
  const to = ['medium', 'high', 'low'].find(n => n !== name && pool.some(r => tierName(score(r)) === n));
  if (to) { quota[to] += quota[name]; quota[name] = 0; }
}
if (!TEST_MODE) {
  const scoreByEmail = new Map(rows.map(r => [String(r.email).toLowerCase(), score(r)]));
  for (const r of sentTodayRows) { const n = tierName(scoreByEmail.get(r.email.toLowerCase()) || 7); quota[n] = Math.max(0, quota[n] - 1); }
}

const openNow = pool.filter(officeOpen).length;   // also evaluated in test mode so the office-hours check is exercised
const eligible = TEST_MODE ? pool : pool.filter(officeOpen);
const picked = [];
for (const name of ['high', 'medium', 'low']) {
  for (const r of eligible.filter(r => tierName(score(r)) === name).slice(0, quota[name])) picked.push(r);
}
const queue = picked.slice(0, remaining);

