  const first = r.first_name ? r.first_name : 'there';
  const subject = SUBJECT;
  const html = `<p>Hi ${first},</p>
<p>In the last 90 days, has ${r.company} turned down a project or stretched the team past its limit?</p>
<p>Most growing agencies have. Capacity, not clients, quietly becomes the ceiling.</p>
<p>${OFFER}</p>
<p>Worth a quick call? <a href="${BOOKING_LINK}">${BOOKING_LINK}</a></p>
<p>${SENDER_NAME}<br>${SENDER_ROLE}, ${SENDER_COMPANY}${SENDER_WEBSITE ? '<br>' + SENDER_WEBSITE : ''}</p>
